* >Natural Source Code: RETENTR
* PROGRAM: RETENTR - RETURN ENTRY (ONLINE)
* DESCRIPTION: INTERACTIVE RETURN CREATION SCREEN
*              ORDER LOOKUP -> LINE SELECTION -> ELIGIBILITY
*              -> RETURN CREATION -> REFUND INITIATION
* LIBRARY: RETAILCORE
* ADABAS FILES: 150 (RETURN), 151 (RETURN-LINE)
* CREATED: 2003-04-15  A. GARCIA
* MODIFIED: 2009-08-22 - ADDED ELIGIBILITY CHECK
* MODIFIED: 2015-03-10 - ADDED RETURN LABEL GENERATION
* MODIFIED: 2021-06-15 - ADDED WEB RETURN SUPPORT
* MODIFIED: 2024-02-10 - ADDED EXCHANGE OPTION
* -------------------------------------------------------
DEFINE DATA
LOCAL USING RET-COPY
LOCAL USING ORD-COPY
LOCAL USING COMMON-COPY
*
LOCAL
  1 #SCREEN-MSG           (A78)
  1 #USER-ID              (A8)
  1 #ORDER-ID             (N10)
  1 #NEW-RET-ID           (N10)
  1 #RET-NUMBER           (A15)
  1 #LINE-IDX             (N3)
  1 #ELIGIBLE-FLAG        (A1)
  1 #ELIG-MSG             (A60)
  1 #VALID-FLAG           (A1)
  1 #ERROR-MSG            (A60)
  1 #ORD-STR              (A15)
  1 #RETURN-TOTAL         (N11.2)
  1 #RETURN-TAX           (N9.2)
*
* ORDER HEADER (FROM ORDGET)
  1 #OH
    2 #OH-ID              (N10)
    2 #OH-NUMBER          (A12)
    2 #OH-CUST-ID         (N8)
    2 #OH-STORE-ID        (N4)
    2 #OH-STATUS          (A3)
    2 #OH-TYPE            (A2)
    2 #OH-DATE            (D)
    2 #OH-NUM-LINES       (N3)
    2 #OH-SUBTOTAL        (N11.2)
    2 #OH-DISCOUNT        (N9.2)
    2 #OH-TAX             (N9.2)
    2 #OH-TOTAL           (N11.2)
    2 #OH-PAID            (N11.2)
    2 #OH-CURRENCY        (A3)
  1 #OL-COUNT             (N3)
  1 #OL-LINES (20)
    2 #OL-NO              (N3)
    2 #OL-PROD-ID         (N8)
    2 #OL-SKU             (A15)
    2 #OL-DESC            (A60)
    2 #OL-QTY             (N6)
    2 #OL-PRICE           (N9.2)
    2 #OL-DISC            (N9.2)
    2 #OL-TAX             (N9.2)
    2 #OL-TOTAL           (N11.2)
    2 #OL-STATUS          (A3)
  1 #FOUND-FLAG           (A1)
  1 #ERR-MSG              (A60)
*
* RETURN LINES
  1 #RET-LINES (20)
    2 #RL-LINE-NO         (N3)
    2 #RL-QTY             (N6)
    2 #RL-REASON          (A4)
    2 #RL-CONDITION       (A1)    /* N=NEW O=OPENED D=DAMAGED */
    2 #RL-REFUND-AMT      (N11.2)
*
  1 RET-VIEW VIEW OF RETURN-FILE
    2 RV-ID                (N10)
    2 RV-NUMBER            (A15)
    2 RV-ORDER-ID          (N10)
    2 RV-CUST-ID           (N8)
    2 RV-STORE-ID          (N4)
    2 RV-STATUS            (A3)
    2 RV-TYPE              (A2)
    2 RV-REASON-CODE       (A4)
    2 RV-NUM-LINES         (N3)
    2 RV-SUBTOTAL          (N11.2)
    2 RV-TAX-AMT           (N9.2)
    2 RV-TOTAL-AMT         (N11.2)
    2 RV-REFUND-METHOD     (A2)
    2 RV-DATE              (D)
    2 RV-CREATED-BY        (A8)
*
  1 RTL-VIEW VIEW OF RETURN-LINE-FILE
    2 RTL-RETURN-ID        (N10)
    2 RTL-LINE-NO          (N3)
    2 RTL-ORDER-LINE-NO    (N3)
    2 RTL-PROD-ID          (N8)
    2 RTL-SKU              (A15)
    2 RTL-QTY-RETURNED     (N6)
    2 RTL-REASON-CODE      (A4)
    2 RTL-CONDITION        (A1)
    2 RTL-UNIT-PRICE       (N9.2)
    2 RTL-REFUND-AMT       (N11.2)
    2 RTL-STATUS           (A3)
END-DEFINE
*
MOVE *USER TO #USER-ID
*
* STEP 1: ORDER LOOKUP
INPUT (IP=ON) WITH TEXT #SCREEN-MSG
  / 'RETAILCORE - RETURN ENTRY' (I)
  / '=========================' (I)
  /
  / 'ORDER ID:' #ORDER-ID (AD=MI)
  /
  / 'PF3=CANCEL  ENTER=LOOK UP ORDER'
*
IF *PF-KEY = 'PF3'
  ESCAPE ROUTINE
END-IF
*
* GET ORDER
CALLNAT 'ORDGET' #ORDER-ID #OH #OL-COUNT #OL-LINES
  #FOUND-FLAG #ERR-MSG
IF #FOUND-FLAG NE 'Y'
  MOVE #ERR-MSG TO #SCREEN-MSG
  ESCAPE ROUTINE
END-IF
*
* CHECK ORDER IS RETURNABLE
IF #OH-STATUS NE 'SHP' AND #OH-STATUS NE 'CMP'
  COMPRESS 'ORDER IN STATUS' #OH-STATUS 'NOT RETURNABLE'
    INTO #SCREEN-MSG
  ESCAPE ROUTINE
END-IF
*
* CHECK RETURN ELIGIBILITY
CALLNAT 'RETCHK' #ORDER-ID #OH-DATE *DATX
  #ELIGIBLE-FLAG #ELIG-MSG
IF #ELIGIBLE-FLAG NE 'Y'
  MOVE #ELIG-MSG TO #SCREEN-MSG
  ESCAPE ROUTINE
END-IF
*
* STEP 2: SELECT LINES TO RETURN
RESET #LINE-IDX
RESET #RETURN-TOTAL
RESET #RETURN-TAX
*
1 #LI (N3)
FOR #LI = 1 TO #OL-COUNT
  IF #OL-LINES.#OL-STATUS(#LI) = 'CAN'
    ESCAPE TOP
  END-IF
*
  INPUT (IP=ON) WITH TEXT #SCREEN-MSG
    / 'RETURN LINE SELECTION'
    / 'ORDER:' #OH-NUMBER (AD=OI)
    /
    / 'LINE :' #OL-LINES.#OL-NO(#LI) (AD=OI)
    / 'SKU  :' #OL-LINES.#OL-SKU(#LI) (AD=OI)
    / 'DESC :' #OL-LINES.#OL-DESC(#LI) (AD=OI)
    / 'QTY  :' #OL-LINES.#OL-QTY(#LI) (AD=OI)
    / 'PRICE:' #OL-LINES.#OL-TOTAL(#LI) (AD=OI)
    /
    / 'RETURN QTY  :' #RET-LINES.#RL-QTY(#LI) (AD=MI)
    / 'REASON CODE :' #RET-LINES.#RL-REASON(#LI) (AD=MI)
    /   '(DEFN=DEFECTIVE WRNG=WRONG DMGD=DAMAGED NOFI=NO FIT'
    /   ' CHGD=CHANGED MIND OTHR=OTHER)'
    / 'CONDITION   :' #RET-LINES.#RL-CONDITION(#LI) (AD=MI)
    /   '(N=NEW/SEALED O=OPENED D=DAMAGED)'
    /
    / 'PF3=DONE  ENTER=NEXT LINE'
*
  IF *PF-KEY = 'PF3'
    ESCAPE BOTTOM
  END-IF
*
  IF #RET-LINES.#RL-QTY(#LI) > 0
    * VALIDATE RETURN QTY
    IF #RET-LINES.#RL-QTY(#LI) > #OL-LINES.#OL-QTY(#LI)
      MOVE 'RETURN QTY EXCEEDS ORDER QTY' TO #SCREEN-MSG
      ESCAPE TOP
    END-IF
    ADD 1 TO #LINE-IDX
    MOVE #OL-LINES.#OL-NO(#LI) TO #RET-LINES.#RL-LINE-NO(#LI)
    * CALCULATE REFUND (PROPORTIONAL)
    COMPUTE #RET-LINES.#RL-REFUND-AMT(#LI) =
      (#OL-LINES.#OL-TOTAL(#LI) / #OL-LINES.#OL-QTY(#LI))
      * #RET-LINES.#RL-QTY(#LI)
    ADD #RET-LINES.#RL-REFUND-AMT(#LI) TO #RETURN-TOTAL
  END-IF
END-FOR
*
IF #LINE-IDX = 0
  MOVE 'NO RETURN LINES SELECTED' TO #SCREEN-MSG
  ESCAPE ROUTINE
END-IF
*
* STEP 3: CONFIRMATION
INPUT (IP=ON)
  / 'RETURN CONFIRMATION' (I)
  / '===================' (I)
  / 'ORDER    :' #OH-NUMBER (AD=OI)
  / 'CUSTOMER :' #OH-CUST-ID (AD=OI)
  / 'LINES    :' #LINE-IDX (AD=OI)
  / 'REFUND   :' #RETURN-TOTAL (AD=OI)
  /
  / 'PF3=CANCEL  ENTER=CREATE RETURN'
*
IF *PF-KEY = 'PF3'
  ESCAPE ROUTINE
END-IF
*
* STEP 4: CREATE RETURN
CALLNAT 'SEQNON' 'RET' #NEW-RET-ID
COMPRESS 'RET-' #NEW-RET-ID INTO #RET-NUMBER LEAVING NO SPACE
*
STORE RET-VIEW
  RV-ID            := #NEW-RET-ID
  RV-NUMBER        := #RET-NUMBER
  RV-ORDER-ID      := #ORDER-ID
  RV-CUST-ID       := #OH-CUST-ID
  RV-STORE-ID      := #OH-STORE-ID
  RV-STATUS        := 'REQ'
  RV-TYPE          := 'RT'
  RV-REASON-CODE   := #RET-LINES.#RL-REASON(1)
  RV-NUM-LINES     := #LINE-IDX
  RV-TOTAL-AMT     := #RETURN-TOTAL
  RV-REFUND-METHOD := 'OR'
  RV-DATE          := *DATX
  RV-CREATED-BY    := #USER-ID
END-STORE
*
* STORE RETURN LINES
1 #RI (N3)
1 #RL-SEQ (N3)
RESET #RL-SEQ
FOR #RI = 1 TO #OL-COUNT
  IF #RET-LINES.#RL-QTY(#RI) > 0
    ADD 1 TO #RL-SEQ
    STORE RTL-VIEW
      RTL-RETURN-ID      := #NEW-RET-ID
      RTL-LINE-NO        := #RL-SEQ
      RTL-ORDER-LINE-NO  := #OL-LINES.#OL-NO(#RI)
      RTL-PROD-ID        := #OL-LINES.#OL-PROD-ID(#RI)
      RTL-SKU            := #OL-LINES.#OL-SKU(#RI)
      RTL-QTY-RETURNED   := #RET-LINES.#RL-QTY(#RI)
      RTL-REASON-CODE    := #RET-LINES.#RL-REASON(#RI)
      RTL-CONDITION      := #RET-LINES.#RL-CONDITION(#RI)
      RTL-UNIT-PRICE     := #OL-LINES.#OL-PRICE(#RI)
      RTL-REFUND-AMT     := #RET-LINES.#RL-REFUND-AMT(#RI)
      RTL-STATUS         := 'REQ'
    END-STORE
  END-IF
END-FOR
*
END OF TRANSACTION
*
* UPDATE ORDER STATUS
CALLNAT 'ORDPOST' #ORDER-ID 'RET' #VALID-FLAG #ERROR-MSG
*
* -------------------------------------------------------
* RETRIEVE CUSTOMER FOR RETURN NOTIFICATIONS
* CREATES CHAIN: RETENTR -> CUSTGET -> VALU/DATEU/CONFIGN/FMTU
* -------------------------------------------------------
1 #RT-CG-DATA
  2 #RT-CD-ID    (N8)
  2 #RT-CD-NO    (A10)
  2 #RT-CD-TYPE  (A2)
  2 #RT-CD-STAT  (A1)
  2 #RT-CD-TITLE (A5)
  2 #RT-CD-FNAME (A30)
  2 #RT-CD-LNAME (A40)
  2 #RT-CD-DOB   (D)
  2 #RT-CD-GEND  (A1)
1 #RT-CG-CONTACT
  2 #RT-CC-EMAIL (A80)
  2 #RT-CC-PH    (A20)
  2 #RT-CC-MOB   (A20)
  2 #RT-CC-WPH   (A20)
1 #RT-CG-ADDR
  2 #RT-CA-ADR1  (A40)
  2 #RT-CA-ADR2  (A40)
  2 #RT-CA-CITY  (A30)
  2 #RT-CA-STATE (A2)
  2 #RT-CA-ZIP   (A10)
  2 #RT-CA-CTRY  (A3)
1 #RT-CG-MEMBER
  2 #RT-CM-FLAG  (A1)
  2 #RT-CM-ID    (A12)
  2 #RT-CM-SINCE (D)
  2 #RT-CM-TIER  (A1)
  2 #RT-CM-PTS   (N10)
  2 #RT-CM-LSPND (N11.2)
  2 #RT-CM-YTDSP (N9.2)
1 #RT-CG-FOUND  (A1)
1 #RT-CG-ERR    (A60)
CALLNAT 'CUSTGET' #OH-CUST-ID #RT-CG-DATA #RT-CG-CONTACT #RT-CG-ADDR
  #RT-CG-MEMBER #RT-CG-FOUND #RT-CG-ERR
*
* REVERSE LOYALTY POINTS FOR RETURN
IF #RT-CG-FOUND = 'Y' AND #RT-CM-FLAG = 'Y'
  1 #RT-REV-POINTS (N10)
  MOVE #RETURN-TOTAL TO #RT-REV-POINTS
  MULTIPLY -1 BY #RT-REV-POINTS
  CALLNAT 'CUSTUPD' #OH-CUST-ID 'LOYL' ' ' 0 ' ' #RT-REV-POINTS
    *DATX 0 ' '
END-IF
*
* REVERSE CUSTOMER SPEND
CALLNAT 'CUSTUPD' #OH-CUST-ID 'SPND' ' ' #RETURN-TOTAL ' ' 0
  *DATX 0 ' '
*
* FORMAT RETURN AMOUNTS FOR DISPLAY
* CREATES CHAIN: RETENTR -> FMTU
1 #RT-FMT-IN  (A80)
1 #RT-FMT-OUT (A132)
CALLNAT 'FMTU' 'CURR' #RT-FMT-IN #RETURN-TOTAL ' ' 0 #RT-FMT-OUT
*
* FORMAT RETURN DATE
* CREATES CHAIN: RETENTR -> DATEU
1 #RT-DT-VALID  (A1)
1 #RT-DT-ERR    (A60)
1 #RT-DT-RESULT (D)
1 #RT-DT-STR    (A10)
1 #RT-DT-NUM    (N5)
CALLNAT 'DATEU' 'FMT' *DATX *DATX 0 #RT-DT-RESULT
  #RT-DT-STR #RT-DT-NUM #RT-DT-VALID #RT-DT-ERR
*
* CALCULATE DAYS SINCE ORDER FOR REPORTING
CALLNAT 'DATEU' 'DIFF' *DATX #OH-DATE 0 #RT-DT-RESULT
  #RT-DT-STR #RT-DT-NUM #RT-DT-VALID #RT-DT-ERR
*
* LOAD RETURN POLICY CONFIGURATION
* CREATES CHAIN: RETENTR -> CONFIGN
1 #RT-CFG-VALUE (A80)
1 #RT-CFG-NUM   (N11.2)
1 #RT-CFG-DATE  (D)
1 #RT-CFG-FLAG  (A1)
1 #RT-CFG-FOUND (A1)
CALLNAT 'CONFIGN' 'RETURN.MAX.DAYS'
  #RT-CFG-VALUE #RT-CFG-NUM #RT-CFG-DATE #RT-CFG-FLAG #RT-CFG-FOUND
CALLNAT 'CONFIGN' 'RETURN.RESTOCK.FEE.PCT'
  #RT-CFG-VALUE #RT-CFG-NUM #RT-CFG-DATE #RT-CFG-FLAG #RT-CFG-FOUND
*
* CHECK INVENTORY FOR RETURNED ITEMS - ADD BACK TO STOCK
* CREATES CHAIN: RETENTR -> INVCHK -> PRODGET -> DATEU/CONFIGN
1 #RT-IC-RESULT
  2 #RT-ICR-OH    (N8)
  2 #RT-ICR-RES   (N8)
  2 #RT-ICR-ALLOC (N8)
  2 #RT-ICR-DMG   (N8)
  2 #RT-ICR-TRANS (N8)
  2 #RT-ICR-AVAIL (N8)
  2 #RT-ICR-SAFE  (N8)
  2 #RT-ICR-REORD (N8)
  2 #RT-ICR-BSAF  (A1)
  2 #RT-ICR-BREOD (A1)
  2 #RT-ICR-SUFF  (A1)
1 #RT-IC-RC     (N4)
1 #RT-IC-MSG    (A80)
1 #RT-IC-LN     (N3)
FOR #RT-IC-LN = 1 TO #OL-COUNT
  IF #RET-LINES.#RL-QTY(#RT-IC-LN) > 0
    CALLNAT 'INVCHK' #OL-LINES.#OL-PROD-ID(#RT-IC-LN)
      #OL-LINES.#OL-SKU(#RT-IC-LN) 'A' 0 0
      #RT-IC-RESULT #RT-IC-RC #RT-IC-MSG
    IF #RT-IC-RC NE 0
      CALLNAT 'LOGERR' #RT-IC-RC #RT-IC-MSG 'W' 'RETENTR' #USER-ID
    END-IF
  END-IF
END-FOR
*
* RETRIEVE PRODUCT DATA FOR FIRST RETURNED ITEM
* CREATES CHAIN: RETENTR -> PRODGET -> DATEU/CONFIGN
1 #RT-PG-PROD-ID (N8)
1 #RT-PG-SKU     (A15)
1 #RT-PG-DATA
  2 #RT-PD-ID    (N8)
  2 #RT-PD-SKU   (A15)
  2 #RT-PD-ITEM  (A12)
  2 #RT-PD-NAME  (A60)
  2 #RT-PD-SHORT (A30)
  2 #RT-PD-LONG  (A200)
  2 #RT-PD-STAT  (A1)
  2 #RT-PD-TYPE  (A2)
  2 #RT-PD-BRAND (A30)
  2 #RT-PD-MFGR  (A40)
  2 #RT-PD-UPC   (A13)
1 #RT-PG-CAT
  2 #RT-PC-DEPT  (A4)
  2 #RT-PC-CLS   (A4)
  2 #RT-PC-SUB   (A4)
  2 #RT-PC-PATH  (A60)
1 #RT-PG-ATTR
  2 #RT-PA-COLOR (A20)
  2 #RT-PA-SIZE  (A10)
  2 #RT-PA-WGHT  (N7.3)
  2 #RT-PA-PRSH  (A1)
  2 #RT-PA-HAZD  (A1)
  2 #RT-PA-SEAS  (A1)
1 #RT-PG-PRICE
  2 #RT-PP-COST  (N9.2)
  2 #RT-PP-PRICE (N9.2)
  2 #RT-PP-MSRP  (N9.2)
  2 #RT-PP-MIN   (N9.2)
  2 #RT-PP-TAX   (A4)
  2 #RT-PP-CURR  (A3)
1 #RT-PG-LIFE
  2 #RT-PL-INT   (D)
  2 #RT-PL-DIS   (D)
  2 #RT-PL-CLR   (D)
  2 #RT-PL-LAST  (D)
1 #RT-PG-FOUND (A1)
1 #RT-PG-ERR   (A60)
1 #RT-FIRST-LN (N3)
FOR #RT-FIRST-LN = 1 TO #OL-COUNT
  IF #RET-LINES.#RL-QTY(#RT-FIRST-LN) > 0
    MOVE #OL-LINES.#OL-PROD-ID(#RT-FIRST-LN) TO #RT-PG-PROD-ID
    MOVE #OL-LINES.#OL-SKU(#RT-FIRST-LN) TO #RT-PG-SKU
    CALLNAT 'PRODGET' #RT-PG-PROD-ID #RT-PG-SKU #RT-PG-DATA #RT-PG-CAT
      #RT-PG-ATTR #RT-PG-PRICE #RT-PG-LIFE #RT-PG-FOUND #RT-PG-ERR
    ESCAPE BOTTOM
  END-IF
END-FOR
*
* AUDIT
MOVE #NEW-RET-ID TO #ORD-STR
CALLNAT 'AUDITN' 'RET' #ORD-STR 'C' 'RETRN'
  ' ' #RET-NUMBER 'RETURN CREATED'
*
COMPRESS 'RETURN' #RET-NUMBER 'CREATED SUCCESSFULLY' INTO #SCREEN-MSG
*
END
